mapper.select:
WITH RECURSIVE dept_subtree AS ( SELECT id, parent_id FROM sys_dept WHERE 1 = 1
AND status = #{query.status}
AND id IN
#{pid}
UNION ALL SELECT c.id, c.parent_id FROM sys_dept c INNER JOIN dept_subtree s ON c.parent_id = s.id
), dept_keyword AS ( SELECT id, parent_id FROM sys_dept WHERE 1 = 1
AND status = #{query.status}
AND (name LIKE CONCAT('%', #{query.keyword}, '%') OR code LIKE CONCAT('%', #{query.keyword}, '%'))
UNION ALL SELECT p.id, p.parent_id FROM sys_dept p INNER JOIN dept_keyword k ON p.id = k.parent_id
) SELECT d.id, d.parent_id, d.name, d.code, d.leader_id, d.status, d.sort_order, d.create_time, d.update_time, lu.nickname AS leader_name, (SELECT COUNT(*) FROM sys_dept_user sdu WHERE sdu.dept_id = d.id) AS user_count FROM sys_dept d LEFT JOIN sys_user lu ON lu.id = d.leader_id WHERE d.id IN (SELECT id FROM dept_subtree) AND d.id IN (SELECT id FROM dept_keyword) ORDER BY d.sort_order, d.id
